1   2   4   4   5   9   6   6 ...Note: With Primitive type focuses on the type of data being primitive.With primitives states that the array or collection is made up of primitive types.Using Arrays.parallelPrefix() with Custom ObjectsHere, we use Arrays.parallelPrefix() with an array of custom Person objects. We modify them by combining attributes like name and age showing how custom operations can be implemented using lambda expressions.
            Java

    import java.util.Arrays;
import java.util.function.BinaryOperator;

public class GFG {

    // User-defined class
    static class Person {
        String n;
        int a;

        // Constructor
        Person(String n, int a) {
            this.n = n;
            this.a = a;
        }
    }

    public static void main(String[] args) {

        // Working with user-defined class
        Person[] p = {
            new Person("Geek1", 10),
            new Person("Geek2", 20),
            new Person("Geek3", 30),
            new Person("Geek4", 40),
            new Person("Geek5", 50),
            new Person("Geek6", 60),
        };

        // Here, we convert the first parameter's name to upper case
        // and then concatenate or add (in case of age) with the 
        // second throughout the array
        Arrays.parallelPrefix(p, new BinaryOperator<Person>() {
            @Override
            public Person apply(Person e1, Person e2) {

                // Modify the name and sum the ages
                return new Person(e1.n.toUpperCase().concat(e2.n), e1.a + e2.a);
            }
        });
        System.out.println("After parallelPrefix for whole array:");

        Arrays.stream(p).forEach(e -> System.out.println(e.n + "   " + e.a));

        // Reset the array for the next example
        Person[] p1 = {
            new Person("Geek1", 10),
            new Person("Geek2", 20),
            new Person("Geek3", 30),
            new Person("Geek4", 40),
            new Person("Geek5", 50),
            new Person("Geek6", 60),
        };

        // This illustrates the same modification but within 
        // a specified range (from index 1 to 4)
        Arrays.parallelPrefix(p1, 1, 4, new BinaryOperator<Person>() {
            @Override
            public Person apply(Person e1, Person e2) {

                // Modify the name and sum the ages
                return new Person(e1.n.toUpperCase().concat(e2.n), e1.a + e2.a);
            }
        });
        System.out.println("\nAfter parallelPrefix for specified range (1 to 4):");

        Arrays.stream(p1).forEach(e -> System.out.println(e.n + "   " + e.a));
    }
}

